b=re.findall(r\"\\w+|["'^'"\\w\\s]\",\"\\\"\\\"\\\"Strongly connected components.\\\"\\\"\\\"  import networkx as nx from networkx.utils.decorators import not_implemented_for  __all__ = [     \\\"number_strongly_connected_components\\\",     \\\"strongly_connected_components\\\",     \\\"is_strongly_connected\\\",     \\\"kosaraju_strongly_connected_components\\\",     \\\"condensation\\\", ]   @not_implemented_for(\\\"undirected\\\") @nx._dispatchable def strongly_connected_components(G):     \\\"\\\"\\\"Generate nodes in strongly connected components of graph.     Parameters     ----------     G : NetworkX Graph         A directed graph.      Returns     -------     comp : generator of sets         A generator of sets of nodes, one for each strongly connected         component of G.      Raises     ------     NetworkXNotImplemented         If G is undirected.      Examples     --------     Generate a sorted list of strongly connected components, largest first.     >>> G = nx.cycle_graph(4, create_using=nx.DiGraph())     >>> nx.add_cycle(G, [10, 11, 12])     >>> [     ...     len(c)     ...     for c in sorted(nx.strongly_connected_components(G), key=len, reverse=True)     ... ]     [4, 3]      If you only want the largest component, it'\\''s more efficient to     use max instead of sort.      >>> largest = max(nx.strongly_connected_components(G), key=len)     See Also     --------     connected_components     weakly_connected_components     kosaraju_strongly_connected_components      Notes     -----     Iterative version of Tarjan'\\''s algorithm using the improvements     described by Tarjan and Zwick in their survey [1]_, plus a trick     borrowed from the Rust implementation of the WebGraph framework [2]_.     References     ----------     .. [1] Robert E. Tarjan and Uri Zwick, \\\"Finding strong components using        depth-first search\\\", European Journal of Combinatorics, 119, 2024.        https://doi.org/10.1016/j.ejc.2023.103815     .. [2] Tommaso Fontana, Sebastiano Vigna, and Stefano Zacchiroli,        \\\"WebGraph: The next generation (is in Rust)\\\", Companion Proceedings        of the ACM Web Conference 2024, pp. 686-689, 2024.        https://doi.org/10.1145/3589335.3651581     \\\"\\\"\\\"     N = len(G)     if N == 0:         return     adj = G._adj     # lowlink[v] doubles as preorder timestamp and low-link: on first visit     # it is set to v'\\''s preorder number and may then only decrease, via     # back / cross arcs, toward the preorder number of some ancestor.     lowlink = {}     scc_found = set()     # Parallel stacks representing the current DFS path. Each frame holds     # (node, iterator over remaining successors, lead flag). A stack     # of triples is measurably slower.     dfs_v = []     dfs_it = []     dfs_lead = []     # Nodes popped from the DFS path but not yet assigned to any SCC.     comp_stack = []     index = 0     for source in G:         if source in lowlink:             continue         index += 1         root_low = index         lowlink[source] = index         dfs_v.append(source)         dfs_it.append(iter(adj[source]))         dfs_lead.append(True)         while dfs_v:             v = dfs_v[-1]             for w in dfs_it[-1]:                 if w not in lowlink:                     # Tree arc: previsit w and descend.                     index += 1                     lowlink[w] = index                     dfs_v.append(w)                     dfs_it.append(iter(adj[w]))                     dfs_lead.append(True)                     break                 # Back/cross arc.                 if w not in scc_found and lowlink[v] > lowlink[w]:                     dfs_lead[-1] = False                     lowlink[v] = lowlink[w]                     # Early exit: every node has been preordered during                     # this DFS tree and v has just linked back to the                     # root, so the whole graph is a single SCC.                     if lowlink[v] == root_low and index == 