or node, label in labeling.items():         clusters[label].add(node)     return clusters.values()   def _color_network(G):     \\\"\\\"\\\"Colors the network so that neighboring nodes all have distinct colors.     Returns a dict keyed by color to a set of nodes with that color.     \\\"\\\"\\\"     coloring = {}  # color => set(node)     colors = nx.coloring.greedy_color(G)     for node, color in colors.items():         if color in coloring:             coloring[color].add(node)         else:             coloring[color] = {node}     return coloring   def _labeling_complete(labeling, G):     \\\"\\\"\\\"Determines whether or not LPA is done.     Label propagation is complete when all nodes have a label that is     in the set of highest frequency labels amongst its neighbors.      Nodes with no neighbors are considered complete.     \\\"\\\"\\\"     return all(         labeling[v] in _most_frequent_labels(v, labeling, G) for v in G if len(G[v]) > 0     )   def _most_frequent_labels(node, labeling, G):     \\\"\\\"\\\"Returns a set of all labels with maximum frequency in "'`labeling`.     Input `labeling` should be a dict keyed by node to labels.     '"\\\"\\\"\\\"     if not G[node]:         # Nodes with no neighbors are themselves a community and are labeled         # accordingly, hence the immediate if statement.         return {labeling[node]}      # Compute the frequencies of all neighbors of node     freqs = Counter(labeling[q] for q in G[node])     max_freq = max(freqs.values())     return {label for label, freq in freqs.items() if freq == max_freq}  def _update_label(node, labeling, G):     \\\"\\\"\\\"Updates the label of a node using the Prec-Max tie breaking algorithm     The algorithm is explained in: '\\''Community Detection via Semi-Synchronous     Label Propagation Algorithms'\\'' Cordasco and Gargano, 2011     \\\"\\\"\\\"     high_labels = _most_frequent_labels(node, labeling, G)     if len(high_labels) == 1:         labeling[node] = high_labels.pop()     elif len(high_labels) > 1:         # Prec-Max         if labeling[node] not in high_labels:             labeling[node] = max(high_labels)\")
