nction        This function filters the nodes chosen. It takes three inputs:        A node of G, the filter'"'\\''s cutoff, and the core dict of the graph.        The function should return a Boolean value.     k : int, optional       The order of the core. If not specified use the max core number.       This value is used as the cutoff for the filter.     core : dict, optional       Precomputed core numbers keyed by node for the graph "'`G`.       If not specified, the core numbers will be computed from `G`.     '"\\\"\\\"\\\"     if core is None:         core = core_number(G)     if k is None:         k = max(core.values())     nodes = (v for v in core if k_filter(v, k, core))     return G.subgraph(nodes).copy()   @nx.utils.not_implemented_for(\\\"multigraph\\\") @nx._dispatchable(preserve_all_attrs=True, returns_graph=True) def k_core(G, k=None, core_number=None):     \\\"\\\"\\\"Returns the k-core of G.      A k-core is a maximal subgraph that contains nodes of degree "'`k` or more.     Parameters     ----------     G : NetworkX graph       A graph or directed graph     k : int, optional       The order of the core. If not specified return the main core.     core_number : dictionary, optional       Precomputed core numbers for the graph G.      Returns     -------     G : NetworkX graph       The k-core subgraph      Raises     ------     NetworkXNotImplemented       The k-core is not defined for multigraphs or graphs with self loops.     Notes     -----     The main core is the core with `k` as the largest core_number.      For directed graphs the node degree is defined to be the     in-degree + out-degree.      Graph, node, and edge attributes are copied to the subgraph.      Examples     --------     >>> degrees = [0, 1, 2, 2, 2, 2, 3]     >>> H = nx.havel_hakimi_graph(degrees)     >>> H.degree     DegreeView({0: 1, 1: 2, 2: 2, 3: 2, 4: 2, 5: 3, 6: 0})     >>> nx.k_core(H).nodes     NodeView((1, 2, 3, 5))     See Also     --------     core_number      References     ----------     .. [1] An O(m) Algorithm for Cores Decomposition of Networks        Vladimir Batagelj and Matjaz Zaversnik,  2003.        https://arxiv.org/abs/cs.DS/0310049     '"\\\"\\\"\\\"      def k_filter(v, k, c):         return c[v] >= k      return _core_subgraph(G, k_filter, k, core_number)  @nx.utils.not_implemented_for(\\\"multigraph\\\") @nx._dispatchable(preserve_all_attrs=True, returns_graph=True) def k_shell(G, k=None, core_number=None):     \\\"\\\"\\\"Returns the k-shell of G.      The k-shell is the subgraph induced by nodes with core number k.     That is, nodes in the k-core that are not in the (k+1)-core.     Parameters     ----------     G : NetworkX graph       A graph or directed graph.     k : int, optional       The order of the shell. If not specified return the outer shell.     core_number : dictionary, optional       Precomputed core numbers for the graph G.       Returns     -------     G : NetworkX graph        The k-shell subgraph      Raises     ------     NetworkXNotImplemented         The k-shell is not implemented for multigraphs or graphs with self loops.     Notes     -----     This is similar to k_corona but in that case only neighbors in the     k-core are considered.      For directed graphs the node degree is defined to be the     in-degree + out-degree.      Graph, node, and edge attributes are copied to the subgraph.     Examples     --------     >>> degrees = [0, 1, 2, 2, 2, 2, 3]     >>> H = nx.havel_hakimi_graph(degrees)     >>> H.degree     DegreeView({0: 1, 1: 2, 2: 2, 3: 2, 4: 2, 5: 3, 6: 0})     >>> nx.k_shell(H, k=1).nodes     NodeView((0, 4))      See Also     --------     core_number     k_corona      References     ----------     .. [1] A model of Internet topology using k-shell decomposition        Shai Carmi, Shlomo Havlin, Scott Kirkpatrick, Yuval Shavitt,        and Eran Shir, PNAS  July 3, 2007   vol. 104  no. 27  11150-11154        http://www.pnas.org/content/104/27/11150.full     \\\"\\\"\\\"      def k_filter(v, k, c):         return c[v] == k      return _core_subgraph(G, k_filter, k, core_number)  @nx.utils.not_implemented_for(\\\"multigraph\\\") @nx._dispatchable(preserve_all_attrs=True, returns_graph=True) def k_crust(G, k=None, core_number=None):     \\\"\\\"\\\"Returns the k-crust of G.      The k-crust is the graph G with the edges of the k-core removed     and isolated nodes found after the removal of edges are also removed.     Parameters     ----------     G : NetworkX graph        A graph or directed graph.     k : int, optional       The order of the shell. If not specified return the main crust.     core_number : dictionary, optional       Precomputed core numbers for the graph G.      Returns     -------     G : NetworkX graph        The k-crust subgraph      Raises     ------     NetworkXNotImplemented         The k-crust is not implemented for multigraphs or graphs with self loops.     Notes     -----     This definition of k-crust is different than the definition in [1]_.     The k-crust in [1]_ is equivalent to the k+1 crust of this algorithm.      For directed graphs the node degree is defined to be the     in-degree + out-degree.      Graph, node, and edge attributes are copied to the subgraph.     Examples     --------     >>> degrees = [0, 1, 2, 2, 2, 2, 3]     >>> H = nx.havel_hakimi_graph(degrees)     >>> H.degree     DegreeView({0: 1, 1: 2, 2: 2, 3: 2, 4: 2, 5: 3, 6: 0})     >>> nx.k_crust(H, k=1).nodes     NodeView((0, 4, 6))      See Also     --------     core_number     References     ----------     .. [1] A model of Internet topology using k-shell decomposition        Shai Carmi, Shlomo Havlin, Scott Kirkpatrick, Yuval Shavitt,        and Eran Shir, PNAS  July 3, 2007   vol. 104  no. 27  11150-11154        http://www.pnas.org/content/104/27/11150.full     \\\"\\\"\\\"     # Default for k is one less than in _core_subgraph, so just inline.     #    Filter is c[v] <= k     if core_number is None:         core_number = nx.core_numb