ber_of_selfloops(G) > 0:         msg = (             \\\"Input graph contains self loops which is not permitted; \\\"             \\\"Consider using G.remove_edges_from(nx.selfloop_edges(G)).\\\"         )         raise nx.NetworkXNotImplemented(msg)     # Dictionaries to register the k-core/onion decompositions.     od_layers = {}     # Adjacency list     neighbors = {v: list(nx.all_neighbors(G, v)) for v in G}     # Effective degree of nodes.     degrees = dict(G.degree())     # Performs the onion decomposition.     current_core = 1     current_layer = 1     # Sets vertices of degree 0 to layer 1, if any.     isolated_nodes = list(nx.isolates(G))     if len(isolated_nodes) > 0:         for v in isolated_nodes:             od_layers[v] = current_layer             degrees.pop(v)         current_layer = 2     # Finds the layer for the remaining nodes.     while len(degrees) > 0:         # Sets the order for looking at nodes.         nodes = sorted(degrees, key=degrees.get)         # Sets properly the current core.         min_degree = degrees[nodes[0]]         if min_degree > current_core:             current_core = min_degree         # Identifies vertices in the current layer.         this_layer = []         for n in nodes:             if degrees[n] > current_core:                 break             this_layer.append(n)         # Identifies the core/layer of the vertices in the current layer.         for v in this_layer:             od_layers[v] = current_layer             for n in neighbors[v]:                 neighbors[n].remove(v)                 degrees[n] = degrees[n] - 1             degrees.pop(v)         # Updates the layer count.         current_layer = current_layer + 1     # Returns the dictionaries containing the onion layer of each vertices.     return od_layers\")
